```

**代码实现：**

```cpp
#include <iostream>
#include <vector>
using namespace std;

int n;
vector<int> path;  // 当前排列
bool used[15];     // 标记数字是否被使用

void dfs(int depth) {
    // 递归边界：已经选择了n个数字
    if (depth == n) {
        for (int i = 0; i < n; i++) {
            cout << path[i];
            if (i < n - 1) cout << " ";
