### 经典例题 5：数字三角形

**题目描述：**
给定一个数字三角形，从顶部出发，每次可以走到下一层相邻的数字，求路径上数字之和的最大值。

**输入样例：**
```
5
7
3 8
8 1 0
2 7 4 4
4 5 2 6 5
```

**输出样例：**
```
30
```

**代码实现：**

```cpp
#include <iostream>
#include <cstring>
#include <algorithm>
using namespace std;

const int MAXN = 105;
int n;
int triangle[MAXN][MAXN];
int dp[MAXN][MAXN];

// 从(i, j)出发到底层的最大和
int dfs(int i, int j) {
    // 边界：到达底层
    if (i == n) return 0;

    // 记忆化
    if (dp[i][j] != -1) return dp[i][j];

    // 状态转移：向下或向右下
    int left = dfs(i + 1, j);
    int right = dfs(i + 1, j + 1);

    dp[i][j] = triangle[i][j] + max(left, right);
    return dp[i][j];
}

int main() {
    cin >> n;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= i; j++) {
            cin >> triangle[i][j];
        }
    }

    memset(dp, -1, sizeof(dp));
    cout << dfs(1, 1) << endl;

    return 0;
}
```

### 经典例题 6：最长上升子序列（LIS）

**题目描述：**
给定一个长度为 $n$ 的序列，求最长上升子序列的长度。

**代码实现（记忆化搜索）：**

```cpp
#include <iostream>
#include <cstring>
#include <algorithm>
using namespace std;

const int MAXN = 1005;
int n;
int arr[MAXN];
int dp[MAXN];  // dp[i] 表示以arr[i]结尾的最长上升子序列长度

// 计算以arr[i]结尾的LIS长度
int dfs(int i) {
    if (dp[i] != -1) return dp[i];

    dp[i] = 1;  // 至少包含自己

    // 枚举前面的元素
    for (int j = 0; j < i; j++) {
        if (arr[j] < arr[i]) {
            dp[i] = max(dp[i], dfs(j) + 1);
        }
    }

    return dp[i];
}

int main() {
    cin >> n;
    for (int i = 0; i < n; i++) {
        cin >> arr[i];
    }

    memset(dp, -1, sizeof(dp));

    int ans = 0;
    for (int i = 0; i < n; i++) {
        ans = max(ans, dfs(i));
    }

    cout << ans << endl;

    return 0;
}
```

