## 4️⃣ 启发式搜索（A* 算法）

**核心思想：** 使用启发函数估计从当前状态到目标状态的代价，优先搜索更有希望的路径。

**评估函数：**
$$f(n) = g(n) + h(n)$$

- $g(n)$：从起点到当前节点的实际代价
- $h(n)$：从当前节点到终点的估计代价（启发函数）
- $f(n)$：总估计代价

**启发函数要求：**
- **可采纳性**：$h(n) \leq h^*(n)$（不高估实际代价）
- **一致性**：$h(n) \leq c(n, n') + h(n')$

**常用启发函数：**
- 曼哈顿距离：$|x_1 - x_2| + |y_1 - y_2|$
- 欧几里得距离：$\sqrt{(x_1-x_2)^2 + (y_1-y_2)^2}$
- 切比雪夫距离：$\max(|x_1-x_2|, |y_1-y_2|)$

### A* 算法模板

```cpp
#include <iostream>
#include <queue>
#include <cstring>
#include <cmath>
using namespace std;

const int MAXN = 1005;
int n, m;
char grid[MAXN][MAXN];
int g[MAXN][MAXN];  // 实际代价
bool visited[MAXN][MAXN];

int dx[] = {-1, 0, 1, 0};
int dy[] = {0, 1, 0, -1};

struct Node {
    int x, y;
    int g;  // 实际代价
    int h;  // 启发代价
    int f;  // 总代价

    bool operator<(const Node& other) const {
        return f > other.f;  // 优先队列小根堆
    }
};

// 曼哈顿距离启发函数
int heuristic(int x1, int y1, int x2, int y2) {
    return abs(x1 - x2) + abs(y1 - y2);
}

int astar(int sx, int sy, int ex, int ey) {
    priority_queue<Node> pq;
    memset(g, 0x3f, sizeof(g));
    memset(visited, false, sizeof(visited));

    g[sx][sy] = 0;
    pq.push({sx, sy, 0, heuristic(sx, sy, ex, ey), heuristic(sx, sy, ex, ey)});

    while (!pq.empty()) {
        Node cur = pq.top();
        pq.pop();

        int x = cur.x, y = cur.y;

        if (visited[x][y]) continue;
        visited[x][y] = true;

        // 到达终点
        if (x == ex && y == ey) {
            return g[x][y];
        }

        // 扩展邻居
        for (int i = 0; i < 4; i++) {
            int nx = x + dx[i];
            int ny = y + dy[i];

            if (nx >= 0 && nx < n && ny >= 0 && ny < m 
                && grid[nx][ny] != '#' && !visited[nx][ny]) {

                int newG = g[x][y] + 1;
                if (newG < g[nx][ny]) {
                    g[nx][ny] = newG;
                    int h = heuristic(nx, ny, ex, ey);
                    pq.push({nx, ny, newG, h, newG + h});
                }
            }
        }
    }

    return -1;  // 无法到达
}

int main() {
    int sx, sy, ex, ey;
    cin >> n >> m;
    for (int i = 0; i < n; i++) {
        cin >> grid[i];
    }
    cin >> sx >> sy >> ex >> ey;

    int result = astar(sx, sy, ex, ey);
    cout << result << endl;

    return 0;
}
```

