## 1️⃣ 基础搜索

### 1.1 广度优先搜索（BFS）

**算法思想：**
- 从起点开始，按照层次顺序依次访问所有节点
- 使用队列（Queue）实现
- 保证找到的第一条路径是最短路径（在无权图中）

**适用场景：**
- 求最短路径（无权图或边权相同）
- 求最少步数
- 层序遍历
- 连通性问题

**时间复杂度：** $O(V + E)$，其中 $V$ 是顶点数，$E$ 是边数

#### 基础模板

```cpp
#include <iostream>
#include <queue>
#include <vector>
#include <cstring>
using namespace std;

const int MAXN = 1005;
int n, m;
int graph[MAXN][MAXN];  // 邻接矩阵
bool visited[MAXN];
int dist[MAXN];  // 距离数组

// BFS 基础模板
void bfs(int start) {
    queue<int> q;
    q.push(start);
    visited[start] = true;
    dist[start] = 0;

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        // 遍历所有邻接节点
        for (int v = 1; v <= n; v++) {
            if (graph[u][v] && !visited[v]) {
                visited[v] = true;
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
}

int main() {
    memset(visited, false, sizeof(visited));
    memset(dist, -1, sizeof(dist));
    // 输入图的信息
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        graph[u][v] = graph[v][u] = 1;  // 无向图
    }

    bfs(1);  // 从节点1开始搜索

    return 0;
}
```

#### 网格图 BFS 模板

```cpp
#include <iostream>
#include <queue>
#include <cstring>
using namespace std;

const int MAXN = 1005;
int n, m;
char grid[MAXN][MAXN];
bool visited[MAXN][MAXN];
int dist[MAXN][MAXN];

// 四个方向：上、右、下、左
int dx[] = {-1, 0, 1, 0};
int dy[] = {0, 1, 0, -1};

struct Point {
    int x, y;
    Point(int _x, int _y) : x(_x), y(_y) {}
};

bool isValid(int x, int y) {
    return x >= 0 && x < n && y >= 0 && y < m;
}

void bfs(int sx, int sy) {
    queue<Point> q;
    q.push(Point(sx, sy));
    visited[sx][sy] = true;
    dist[sx][sy] = 0;

    while (!q.empty()) {
        Point cur = q.front();
        q.pop();

        // 遍历四个方向
        for (int i = 0; i < 4; i++) {
            int nx = cur.x + dx[i];
            int ny = cur.y + dy[i];

            if (isValid(nx, ny) && !visited[nx][ny] && grid[nx][ny] != '#') {
                visited[nx][ny] = true;
                dist[nx][ny] = dist[cur.x][cur.y] + 1;
                q.push(Point(nx, ny));
            }
        }
    }
}

int main() {
    cin >> n >> m;
    for (int i = 0; i < n; i++) {
        cin >> grid[i];
    }

    memset(visited, false, sizeof(visited));
    memset(dist, -1, sizeof(dist));

    bfs(0, 0);  // 从(0,0)开始搜索

    return 0;
}
```

#### 经典例题 1：走迷宫

**题目描述：**
给定一个 $n \times m$ 的迷宫，其中 `'.'` 表示可以通行，`'#'` 表示障碍物，`'S'` 表示起点，`'E'` 表示终点。求从起点到终点的最短路径长度。

**输入样例：**
```
5 5
S....
.###.
.#...
.#.#.
....E
```

**输出样例：**
```
9
```

**代码实现：**

```cpp
#include <iostream>
#include <queue>
#include <cstring>
using namespace std;

const int MAXN = 1005;
int n, m;
char maze[MAXN][MAXN];
int dist[MAXN][MAXN];
int sx, sy, ex, ey;  // 起点和终点坐标

int dx[] = {-1, 0, 1, 0};
int dy[] = {0, 1, 0, -1};

struct Point {
    int x, y;
};

int bfs() {
    queue<Point> q;
    q.push({sx, sy});
    memset(dist, -1, sizeof(dist));
    dist[sx][sy] = 0;

    while (!q.empty()) {
        Point cur = q.front();
        q.pop();

        // 到达终点
        if (cur.x == ex && cur.y == ey) {
            return dist[ex][ey];
        }

        for (int i = 0; i < 4; i++) {
            int nx = cur.x + dx[i];
            int ny = cur.y + dy[i];

            if (nx >= 0 && nx < n && ny >= 0 && ny < m 
                && maze[nx][ny] != '#' && dist[nx][ny] == -1) {
                dist[nx][ny] = dist[cur.x][cur.y] + 1;
                q.push({nx, ny});
            }
        }
    }

    return -1;  // 无法到达终点
}

int main() {
    cin >> n >> m;
    for (int i = 0; i < n; i++) {
        cin >> maze[i];
        for (int j = 0; j < m; j++) {
            if (maze[i][j] == 'S') {
                sx = i; sy = j;
            }
            if (maze[i][j] == 'E') {
                ex = i; ey = j;
            }
        }
    }

    int result = bfs();
    if (result == -1) {
        cout << "无法到达终点" << endl;
    } else {
        cout << result << endl;
    }

    return 0;
}
```

