### 经典例题 7：埃及分数

**题目描述：**
将分数 $\frac{a}{b}$ 表示为若干个不同的单位分数之和，求字典序最小的方案。

例如：$\frac{2}{3} = \frac{1}{2} + \frac{1}{6}$

**代码实现：**

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int a, b;
vector<int> ans, path;
int maxDepth;

// 计算最少需要多少个分数
int heuristic(int a, int b) {
    if (a == 0) return 0;
    return (b + a - 1) / a;  // 上取整
}

// 比较两个方案的字典序
bool better(vector<int>& a, vector<int>& b) {
    if (a.size() != b.size()) return a.size() < b.size();
    return a < b;
}

// depth: 当前深度, from: 上一个分母
bool dfs(int depth, int from, int aa, int bb, int limit) {
    if (depth + heuristic(aa, bb) > limit) return false;

    if (aa == 0) {
        if (ans.empty() || better(path, ans)) {
            ans = path;
        }
        return true;
    }

    // 枚举下一个分母
    int minC = max(from + 1, bb / aa + 1);
    for (int c = minC; c <= limit * bb; c++) {
        // aa/bb - 1/c = (aa*c - bb) / (bb*c)
        int numa = aa * c - bb;
        int deno = bb * c;

        if (numa <= 0) continue;

        path.push_back(c);
        if (dfs(depth + 1, c, numa, deno, limit)) {
            return true;
        }
        path.pop_back();
    }

    return false;
}

void solve() {
    for (int limit = 1; limit <= 10; limit++) {
        ans.clear();
        path.clear();
        if (dfs(0, 0, a, b, limit)) {
            cout << a << "/" << b << " = ";
            for (int i = 0; i < ans.size(); i++) {
                cout << "1/" << ans[i];
                if (i < ans.size() - 1) cout << " + ";
            }
            cout << endl;
            return;
        }
    }
}

int main() {
    cin >> a >> b;
    solve();
    return 0;
}
```

