## 4️⃣ 数位DP

**核心思想：** 按数位逐位构造数字，统计满足条件的数字个数。

**适用场景：**
- 统计区间 $[L, R]$ 内满足某种性质的数字个数
- 性质通常与数位有关

**基本框架：**
- `dp[pos][state][limit]`
  - `pos`: 当前处理的数位
  - `state`: 状态（如前导零、数字和等）
  - `limit`: 是否受到原数限制

### 经典例题：数字计数

**问题描述：**
统计区间 $[L, R]$ 中数字 $d$ 出现的次数。

#### 代码实现

```cpp
#include <iostream>
#include <cstring>
using namespace std;

long long dp[20][20];  // dp[pos][cnt] 表示第pos位，已经有cnt个d的方案数
int digits[20];
int d;  // 要统计的数字

// pos: 当前位, cnt: 已有d的个数, limit: 是否受限, leadZero: 是否有前导零
long long dfs(int pos, int cnt, bool limit, bool leadZero) {
    if (pos == -1) return cnt;

    if (!limit && !leadZero && dp[pos][cnt] != -1) {
        return dp[pos][cnt];
    }

    int up = limit ? digits[pos] : 9;
    long long res = 0;

    for (int i = 0; i <= up; i++) {
        // 跳过前导零的情况
        if (leadZero && i == 0) {
            res += dfs(pos - 1, cnt, limit && i == up, true);
        } else {
            res += dfs(pos - 1, cnt + (i == d), limit && i == up, false);
        }
    }

    if (!limit && !leadZero) {
        dp[pos][cnt] = res;
    }

    return res;
}

long long count(long long x) {
    if (x < 0) return 0;

    int len = 0;
    while (x) {
        digits[len++] = x % 10;
        x /= 10;
    }

    return dfs(len - 1, 0, true, true);
}

int main() {
    long long L, R;
    cin >> L >> R >> d;

    memset(dp, -1, sizeof(dp));
    cout << count(R) - count(L - 1) << endl;

    return 0;
}
```

