### 树的重心

**问题描述：**
找到树的重心（删除后使得各连通块大小最大值最小的节点）。

**状态定义：**
- `size[u]` 表示以 $u$ 为根的子树大小
- `maxPart[u]` 表示删除 $u$ 后最大连通块大小

#### 代码实现

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const int MAXN = 100005;
int n;
vector<int> tree[MAXN];
int size[MAXN];
int maxPart[MAXN];
int centroid = -1;
int minMaxPart = MAXN;

void dfs(int u, int parent) {
    size[u] = 1;
    maxPart[u] = 0;

    for (int v : tree[u]) {
        if (v == parent) continue;

        dfs(v, u);

        size[u] += size[v];
        maxPart[u] = max(maxPart[u], size[v]);
    }

    maxPart[u] = max(maxPart[u], n - size[u]);

    if (maxPart[u] < minMaxPart) {
        minMaxPart = maxPart[u];
        centroid = u;
    }
}

int main() {
    cin >> n;
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        cin >> u >> v;
        tree[u].push_back(v);
        tree[v].push_back(u);
    }

    dfs(1, -1);
    cout << "树的重心: " << centroid << endl;
    cout << "最大连通块大小: " << minMaxPart << endl;

    return 0;
}
```

