### 2.3 多重背包

**问题描述：**
有 $n$ 种物品，第 $i$ 种物品有 $c_i$ 个，求最大价值。

**优化方法：** 二进制拆分

将 $c_i$ 个物品拆分成 $\log c_i$ 组：$1, 2, 4, ..., 2^k, c_i - 2^{k+1} + 1$

#### 代码实现

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

struct Item {
    int w, v;
};

int knapsack_multiple(int n, int W, vector<int>& weight, vector<int>& value, vector<int>& count) {
    vector<Item> items;

    // 二进制拆分
    for (int i = 0; i < n; i++) {
        int c = count[i];
        for (int k = 1; k <= c; k *= 2) {
            items.push_back({weight[i] * k, value[i] * k});
            c -= k;
        }
        if (c > 0) {
            items.push_back({weight[i] * c, value[i] * c});
        }
    }

    // 转化为0-1背包
    vector<int> dp(W + 1, 0);
    for (auto& item : items) {
        for (int j = W; j >= item.w; j--) {
            dp[j] = max(dp[j], dp[j - item.w] + item.v);
        }
    }

    return dp[W];
}
```

