## 4. 高精度乘法

### 4.1 算法思路

**情况一：高精度 × 低精度**（最常用）

模拟竖式乘法：
1. 用高精度数的每一位乘以低精度数
2. 处理进位
3. 时间复杂度：$O(n)$

**情况二：高精度 × 高精度**

使用竖式乘法的思想，时间复杂度：$O(n^2)$

### 4.2 图解示例（高精度 × 低精度）

```
      1 2 3
    ×     7
    -------
      8 6 1
```

### 4.3 完整代码实现

#### 4.3.1 高精度 × 低精度

```cpp
#include <bits/stdc++.h>
using namespace std;

// 高精度乘法：A × b（b 是普通整数）
vector<int> mul(vector<int> &A, int b) {
    vector<int> C;
    int carry = 0;

    for (int i = 0; i < A.size() || carry; i++) {
        if (i < A.size()) carry += A[i] * b;
        C.push_back(carry % 10);
        carry /= 10;
    }

    // 去除前导零（处理 b = 0 的情况）
    while (C.size() > 1 && C.back() == 0) C.pop_back();

    return C;
}

int main() {
    string a;
    int b;
    cin >> a >> b;

    vector<int> A;
    for (int i = a.size() - 1; i >= 0; i--) A.push_back(a[i] - '0');

    vector<int> C = mul(A, b);

    for (int i = C.size() - 1; i >= 0; i--) cout << C[i];
    cout << endl;

    return 0;
}
```

#### 4.3.2 高精度 × 高精度

```cpp
#include <bits/stdc++.h>
using namespace std;

// 高精度乘法：A × B
vector<int> mul(vector<int> &A, vector<int> &B) {
    vector<int> C(A.size() + B.size(), 0);  // 结果最多 A.size() + B.size() 位

    // 模拟竖式乘法
    for (int i = 0; i < A.size(); i++) {
        for (int j = 0; j < B.size(); j++) {
            C[i + j] += A[i] * B[j];
        }
    }

    // 处理进位
    int carry = 0;
    for (int i = 0; i < C.size(); i++) {
        carry += C[i];
        C[i] = carry % 10;
        carry /= 10;
    }

    // 去除前导零
    while (C.size() > 1 && C.back() == 0) C.pop_back();

    return C;
}

int main() {
    string a, b;
    cin >> a >> b;

    vector<int> A, B;
    for (int i = a.size() - 1; i >= 0; i--) A.push_back(a[i] - '0');
    for (int i = b.size() - 1; i >= 0; i--) B.push_back(b[i] - '0');

    vector<int> C = mul(A, B);

    for (int i = C.size() - 1; i >= 0; i--) cout << C[i];
    cout << endl;

    return 0;
}
```

