        carry += C[i];
        C[i] = carry % 10;
        carry /= 10;
    }

    // 去除前导零
    while (C.size() > 1 && C.back() == 0) C.pop_back();

    return C;
}

int main() {
    string a, b;
    cin >> a >> b;

    vector<int> A, B;
    for (int i = a.size() - 1; i >= 0; i--) A.push_back(a[i] - '0');
    for (int i = b.size() - 1; i >= 0; i--) B.push_back(b[i] - '0');

    vector<int> C = mul(A, B);

    for (int i = C.size() - 1; i >= 0; i--) cout << C[i];
    cout << endl;

    return 0;
}
```

---

## 5. 高精度除法

### 5.1 算法思路

**高精度 ÷ 低精度**（最常用）

模拟手工长除法：
1. 从高位到低位处理
2. 每次取当前位和余数组成新的被除数
3. 计算商和余数
4. 注意：结果需要翻转（因为从高位到低位计算）

**时间复杂度：** $O(n)$

### 5.2 图解示例

```
    1 2 3 4 ÷ 5 = 246 ... 4
```

### 5.3 完整代码实现

```cpp
#include <bits/stdc++.h>
using namespace std;

// 高精度除法：A ÷ b（b 是普通整数）
// 返回商 C 和余数 r
vector<int> div(vector<int> &A, int b, int &r) {
    vector<int> C;
    r = 0;  // 余数

    // 从高位到低位处理（所以要倒着遍历）
    for (int i = A.size() - 1; i >= 0; i--) {
        r = r * 10 + A[i];  // 组成新的被除数
        C.push_back(r / b);  // 当前位的商
        r %= b;  // 更新余数
    }

    // 反转结果（因为是从高位到低位计算的）
    reverse(C.begin(), C.end());

    // 去除前导零
    while (C.size() > 1 && C.back() == 0) C.pop_back();

    return C;
}

int main() {
    string a;
    int b;
    cin >> a >> b;

    vector<int> A;
    for (int i = a.size() - 1; i >= 0; i--) A.push_back(a[i] - '0');

    int r;  // 余数
    vector<int> C = div(A, b, r);

    // 输出商
    for (int i = C.size() - 1; i >= 0; i--) cout << C[i];
    cout << endl;

    // 输出余数
    cout << "余数: " << r << endl;

    return 0;
}
```

---

## 6. 高精度算法模板总结

### 6.1 快速使用模板

```cpp
// 高精度加法
vector<int> add(vector<int> &A, vector<int> &B);

// 高精度减法（A >= B）
vector<int> sub(vector<int> &A, vector<int> &B);

// 高精度乘法（A × b）
vector<int> mul(vector<int> &A, int b);

// 高精度除法（A ÷ b，返回商和余数）
vector<int> div(vector<int> &A, int b, int &r);
```

### 6.2 常用技巧

1. **字符串转数组：**
```cpp
vector<int> A;
for (int i = a.size() - 1; i >= 0; i--) 
    A.push_back(a[i] - '0');
```

2. **数组转字符串输出：**
```cpp
for (int i = C.size() - 1; i >= 0; i--) 
    cout << C[i];
```

3. **去除前导零：**
```cpp
while (C.size() > 1 && C.back() == 0) 
    C.pop_back();
```

### 6.3 注意事项

1. **存储方式：** 采用逆序存储（低位在前）
2. **边界情况：** 注意处理 0、负数、前导零
3. **内存优化：** 可以使用 `vector<int>` 或 `string` 存储
4. **进制选择：** 可以使用万进制优化（存储 4 位一组）

---

## 7. 经典例题

### 7.1 阶乘计算

**问题：** 计算 $n!$（$n \leq 1000$）

```cpp
#include <bits/stdc++.h>
using namespace std;

vector<int> mul(vector<int> &A, int b) {
    vector<int> C;
    int carry = 0;
    for (int i = 0; i < A.size() || carry; i++) {
        if (i < A.size()) carry += A[i] * b;
        C.push_back(carry % 10);
        carry /= 10;
    }
    return C;
}

int main() {
    int n;
    cin >> n;

    vector<int> result = {1};  // 初始化为 1

    // 计算 n!
    for (int i = 2; i <= n; i++) {
        result = mul(result, i);
    }

    // 输出结果
    for (int i = result.size() - 1; i >= 0; i--) 
        cout << result[i];
    cout << endl;

    return 0;
}
```

### 7.2 斐波那契数列

**问题：** 计算第 $n$ 个斐波那契数（$n \leq 10000$）

```cpp
#include <bits/stdc++.h>
using namespace std;

vector<int> add(vector<int> &A, vector<int> &B) {
    vector<int> C;
    int carry = 0;
    for (int i = 0; i < A.size() || i < B.size(); i++) {
        if (i < A.size()) carry += A[i];
        if (i < B.size()) carry += B[i];
        C.push_back(carry % 10);
        carry /= 10;
    }
    if (carry) C.push_back(carry);
    return C;
}

int main() {
    int n;
    cin >> n;

    vector<int> f1 = {1}, f2 = {1};

    for (int i = 3; i <= n; i++) {
        vector<int> f3 = add(f1, f2);
        f1 = f2;
        f2 = f3;
    }

    for (int i = f2.size() - 1; i >= 0; i--) 
        cout << f2[i];
    cout << endl;

    return 0;
}
```

---

## 8. 性能优化

### 8.1 万进制优化

将每 4 位十进制数存为一个单位，可以提升 4 倍效率：

```cpp
// 万进制高精度加法
vector<int> add(vector<int> &A, vector<int> &B) {
    vector<int> C;
    int carry = 0;
    for (int i = 0; i < A.size() || i < B.size(); i++) {
        if (i < A.size()) carry += A[i];
        if (i < B.size()) carry += B[i];
        C.push_back(carry % 10000);
        carry /= 10000;
    }
    if (carry) C.push_back(carry);
    return C;
}
```

### 8.2 使用 Python

对于高精度运算，Python 原生支持大整数：

