### 3.3 stack（栈）

```cpp
#include <iostream>
#include <stack>
using namespace std;

int main() {
    stack<int> stk;

    // 入栈
    stk.push(1);
    stk.push(2);
    stk.push(3);

    // 栈顶元素
    cout << "top: " << stk.top() << endl;

    // 出栈
    stk.pop();
    cout << "top after pop: " << stk.top() << endl;

    // 大小和判空
    cout << "size: " << stk.size() << endl;
    cout << "empty: " << stk.empty() << endl;

    // 遍历（需要边遍历边弹出）
    while (!stk.empty()) {
        cout << stk.top() << " ";
        stk.pop();
    }
    cout << endl;

    return 0;
}
```

**应用：括号匹配**

```cpp
bool isValid(string s) {
    stack<char> stk;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            stk.push(c);
        } else {
            if (stk.empty()) return false;
            char top = stk.top();
            if ((c == ')' && top == '(') ||
                (c == ']' && top == '[') ||
                (c == '}' && top == '{')) {
                stk.pop();
            } else {
                return false;
            }
        }
    }
    return stk.empty();
}
```

