    if (mp.find("apple") != mp.end()) {
        cout << "找到apple" << endl;
    }

    if (mp.count("pear") == 0) {
        cout << "没有pear" << endl;
    }

    // 遍历
    for (auto &p : mp) {
        cout << p.first << ": " << p.second << endl;
    }

    // 或者
    for (auto it = mp.begin(); it != mp.end(); it++) {
        cout << it->first << ": " << it->second << endl;
    }

    // 删除
    mp.erase("banana");

    // 大小
    cout << "size: " << mp.size() << endl;

    return 0;
}
```

