```c
#include <stdio.h>

// 函数声明
int add(int a, int b);
void swap(int *a, int *b);  // 指针参数
int max(int a, int b);

int main() {
    int x = 10, y = 20;

    // 函数调用
    int sum = add(x, y);
    printf("sum = %d\n", sum);

    // 传递指针修改变量
    swap(&x, &y);
    printf("x = %d, y = %d\n", x, y);

    return 0;
}

// 函数定义
int add(int a, int b) {
    return a + b;
}

void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

int max(int a, int b) {
    return (a > b) ? a : b;
}
```

#### 递归函数

```c
#include <stdio.h>

// 阶乘
int factorial(int n) {
    if (n <= 1) return 1;
    return n * factorial(n - 1);
}

// 斐波那契数列
int fibonacci(int n) {
    if (n <= 1) return n;
    return fibonacci(n - 1) + fibonacci(n - 2);
}

// 最大公约数（欧几里得算法）
int gcd(int a, int b) {
    if (b == 0) return a;
    return gcd(b, a % b);
}

int main() {
    printf("5! = %d\n", factorial(5));
    printf("fib(10) = %d\n", fibonacci(10));
    printf("gcd(48, 18) = %d\n", gcd(48, 18));

    return 0;
}
```

