```c
#include <stdio.h>
#include <string.h>

// 定义结构体
struct Student {
    int id;
    char name[50];
    float score;
};

int main() {
    // 声明和初始化
    struct Student s1 = {1, "张三", 95.5};

    // 访问成员
    printf("学号: %d\n", s1.id);
    printf("姓名: %s\n", s1.name);
    printf("成绩: %.1f\n", s1.score);

    // 修改成员
    s1.score = 98.0;
    strcpy(s1.name, "李四");

    // 结构体指针
    struct Student *p = &s1;
    printf("通过指针访问: %d, %s, %.1f\n", 
           p->id, p->name, p->score);

    // 结构体数组
    struct Student students[3] = {
        {1, "张三", 95.5},
        {2, "李四", 88.0},
        {3, "王五", 92.3}
    };

    for (int i = 0; i < 3; i++) {
        printf("%d: %s - %.1f\n", 
               students[i].id, 
               students[i].name, 
               students[i].score);
    }

    return 0;
}
