### 3.5 priority_queue（优先队列/堆）

```cpp
#include <iostream>
#include <queue>
#include <vector>
using namespace std;

int main() {
    // 默认是大根堆（最大元素在堆顶）
    priority_queue<int> maxHeap;

    maxHeap.push(3);
    maxHeap.push(1);
    maxHeap.push(4);
    maxHeap.push(1);
    maxHeap.push(5);

    while (!maxHeap.empty()) {
        cout << maxHeap.top() << " ";
        maxHeap.pop();
    }
    cout << endl;  // 输出: 5 4 3 1 1

    // 小根堆（最小元素在堆顶）
    priority_queue<int, vector<int>, greater<int>> minHeap;

    minHeap.push(3);
    minHeap.push(1);
    minHeap.push(4);
    minHeap.push(1);
    minHeap.push(5);

    while (!minHeap.empty()) {
        cout << minHeap.top() << " ";
        minHeap.pop();
    }
    cout << endl;  // 输出: 1 1 3 4 5

    return 0;
}
```

