### 3.6 set（集合）

```cpp
#include <iostream>
#include <set>
using namespace std;

int main() {
    // set：有序、不重复
    set<int> s;

    // 插入
    s.insert(3);
    s.insert(1);
    s.insert(4);
    s.insert(1);  // 重复元素不会插入
    s.insert(5);

    // 遍历（自动排序）
    for (int x : s) {
        cout << x << " ";
    }
    cout << endl;  // 输出: 1 3 4 5

    // 查找
    if (s.find(3) != s.end()) {
        cout << "找到3" << endl;
    }

    // 计数
    cout << "1的个数: " << s.count(1) << endl;  // 只能是0或1

    // 删除
    s.erase(3);     // 删除值为3的元素
    s.erase(s.begin());  // 删除迭代器指向的元素

    // 大小
    cout << "size: " << s.size() << endl;

    // lower_bound和upper_bound
    set<int> nums = {1, 3, 5, 7, 9};
    auto it1 = nums.lower_bound(5);  // 第一个>=5的元素
    auto it2 = nums.upper_bound(5);  // 第一个>5的元素

    cout << "lower_bound(5): " << *it1 << endl;  // 5
    cout << "upper_bound(5): " << *it2 << endl;  // 7

    return 0;
}
```

