### 3.7 map（映射）

```cpp
#include <iostream>
#include <map>
#include <string>
using namespace std;

int main() {
    // map：键值对，按键自动排序
    map<string, int> mp;

    // 插入
    mp["apple"] = 3;
    mp["banana"] = 5;
    mp["orange"] = 2;
    mp.insert({"grape", 4});

    // 访问
    cout << "apple: " << mp["apple"] << endl;

    // 判断键是否存在
    if (mp.find("apple") != mp.end()) {
        cout << "找到apple" << endl;
    }

    if (mp.count("pear") == 0) {
        cout << "没有pear" << endl;
    }

    // 遍历
    for (auto &p : mp) {
        cout << p.first << ": " << p.second << endl;
    }

    // 或者
    for (auto it = mp.begin(); it != mp.end(); it++) {
        cout << it->first << ": " << it->second << endl;
    }

    // 删除
    mp.erase("banana");

    // 大小
    cout << "size: " << mp.size() << endl;

    return 0;
}
```

